CREATE TABLE IF NOT EXISTS profiles (id uuid PRIMARY KEY, username VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL, last_modified_at TIMESTAMP NOT NULL, last_synced_at TIMESTAMP NULL, deleted_at TIMESTAMP NULL);
ALTER TABLE profiles ADD CONSTRAINT profiles_username_unique UNIQUE (username);
ALTER TABLE profiles ADD CONSTRAINT profiles_email_unique UNIQUE (email);
CREATE TABLE IF NOT EXISTS foods (id uuid PRIMARY KEY, profile_id uuid NOT NULL, client_id uuid NOT NULL, "name" VARCHAR(255) NOT NULL, kilo_calories INT NULL, kilo_joule INT NULL, fat_in_grams REAL NULL, saturated_fatty_acids_in_grams REAL NULL, carbs_in_grams REAL NULL, sugar_in_grams REAL NULL, dietary_fiber_in_grams REAL NULL, protein_in_grams REAL NULL, salt_in_grams REAL NULL, filling_quantity REAL NULL, is_liquid BOOLEAN DEFAULT FALSE NOT NULL, best_before_used_by_date DATE NULL, is_use_by BOOLEAN NOT NULL, opened_at DATE NULL, created_at TIMESTAMP NOT NULL, last_modified_at TIMESTAMP NOT NULL, deleted_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS inventory_items (id uuid PRIMARY KEY, client_id uuid NOT NULL, "name" VARCHAR(255) NOT NULL, kilo_calories INT NULL, kilo_joule INT NULL, fat_in_grams REAL NULL, saturated_fatty_acids_in_grams REAL NULL, carbs_in_grams REAL NULL, sugar_in_grams REAL NULL, dietary_fiber_in_grams REAL NULL, protein_in_grams REAL NULL, salt_in_grams REAL NULL, filling_quantity REAL NULL, is_liquid BOOLEAN DEFAULT FALSE NOT NULL, profile_id uuid NOT NULL, created_at TIMESTAMP NOT NULL, last_modified_at TIMESTAMP NOT NULL, deleted_at TIMESTAMP NULL);
CREATE TABLE IF NOT EXISTS images (id uuid PRIMARY KEY, profile_id uuid NOT NULL, food_id uuid NULL, inventory_item_id uuid NULL, is_primary BOOLEAN DEFAULT FALSE NOT NULL, created_at TIMESTAMP NOT NULL, last_modified_at TIMESTAMP NOT NULL, deleted_at TIMESTAMP NULL);
